# lending-desk

The lending desk service of the city library's branches: checkouts, returns, renewals, holds, fees,
notices to members, and the self-check machines.

Plain Node.js ES modules, no dependencies. Node.js 22 or later.

```sh
npm test    # runs every test in test/
npm start   # serves the API on port 8080, with demo data
```
import { LOAN_RULES } from '../config/defaults.js';
import { addDays, nextOpenDay } from '../helpers/dates.js';

/**
 * Returns the day a loan of an item of this format, lent or renewed on `checkedOutOn`, falls due:
 * the end of the format's loan period, or the branch's next open day after it.
 */
export function computeDueDate({ checkedOutOn, format, branch }) {
  return nextOpenDay(branch, addDays(checkedOutOn, LOAN_RULES[format].loanDays));
}
import { normaliseBarcode } from '../catalog/barcodes.js';
import { isLendable } from '../catalog/items.js';
import { branchById } from '../config/branches.js';
import { canBorrow } from '../members/eligibility.js';
import { computeDueDate } from './due-dates.js';

/** Lends an item to a member. Returns { ok: true, loan } or { ok: false, reason }. */
export function checkOutItem(store, { barcode, memberId, today }) {
  const item = store.findItemByBarcode(normaliseBarcode(barcode));
  if (item === undefined) return { ok: false, reason: 'unknown-item' };
  const member = store.getMember(memberId);
  if (member === undefined) return { ok: false, reason: 'unknown-member' };
  if (!isLendable(item)) return { ok: false, reason: 'not-lendable' };
  if (store.findOpenLoan(item.id) !== undefined) return { ok: false, reason: 'on-loan' };
  if (findBlockingHold(store, item.id, member.id) !== null) return { ok: false, reason: 'on-hold' };
  const eligibility = canBorrow(store, member, today);
  if (!eligibility.ok) return eligibility;
  const loan = store.saveLoan({
    itemId: item.id,
    memberId: member.id,
    checkedOutOn: today,
    dueOn: computeDueDate({ checkedOutOn: today, format: item.format, branch: branchById(item.branchId) }),
    renewals: 0,
    returnedOn: null,
  });
  for (const hold of store.listHolds(item.id)) {
    if (hold.memberId === member.id && hold.status !== 'expired') {
      store.saveHold({ ...hold, status: 'collected' });
    }
  }
  return { ok: true, loan };
}

/** Returns the hold of another member that keeps an item from being lent, or null when none does. */
export function findBlockingHold(store, itemId, memberId) {
  const active = store
    .listHolds(itemId)
    .filter((hold) => hold.status === 'waiting' || hold.status === 'ready');
  return active.find((hold) => hold.memberId !== memberId) ?? null;
}
import { branchById } from '../config/branches.js';
import { LOAN_RULES } from '../config/defaults.js';
import { computeDueDate } from './due-dates.js';

/**
 * Renews a loan from today for a new loan period. Returns { ok: true, loan } or
 * { ok: false, reason }.
 */
export function renewLoan(store, { loanId, today }) {
  const loan = store.getLoan(loanId);
  if (loan === undefined || loan.returnedOn !== null) return { ok: false, reason: 'unknown-loan' };
  if (loan.dueOn < today) return { ok: false, reason: 'overdue' };
  const item = store.getItem(loan.itemId);
  if (loan.renewals >= LOAN_RULES[item.format].maxRenewals) return { ok: false, reason: 'renewal-limit' };
  const dueOn = computeDueDate({
    checkedOutOn: today,
    format: item.format,
    branch: branchById(item.branchId),
  });
  return { ok: true, loan: store.saveLoan({ ...loan, renewals: loan.renewals + 1, dueOn }) };
}
export { checkOutItem, findBlockingHold } from './checkout.js';
export { computeDueDate } from './due-dates.js';
export { renewLoan } from './renewals.js';
export { returnItem } from './returns.js';
/** The branches of the library. Weekdays are 0 for Sunday to 6 for Saturday. */
export const BRANCHES = [
  {
    id: 'central',
    name: 'Central Library',
    closedWeekdays: [0],
    holidays: ['2026-12-25', '2027-01-01', '2027-05-31'],
  },
  {
    id: 'riverside',
    name: 'Riverside Branch',
    closedWeekdays: [0, 1],
    holidays: ['2026-12-24', '2026-12-25', '2027-01-01'],
  },
  {
    id: 'hillcrest',
    name: 'Hillcrest Branch',
    closedWeekdays: [0, 6],
    holidays: ['2026-12-25', '2027-01-01'],
  },
];

/** Returns the branch with this id, and throws for an id that is not one. */
export function branchById(id) {
  const branch = BRANCHES.find((candidate) => candidate.id === id);
  if (branch === undefined) throw new Error(`Unknown branch ${id}`);
  return branch;
}
/** How long each format is lent for, in days, and how many times a loan of it may be renewed. */
export const LOAN_RULES = {
  book: { loanDays: 21, maxRenewals: 2 },
  dvd: { loanDays: 7, maxRenewals: 1 },
  magazine: { loanDays: 7, maxRenewals: 0 },
  laptop: { loanDays: 1, maxRenewals: 0 },
};

/** How many items a member of each type may have on loan at once. */
export const MAX_ITEMS_ON_LOAN = { adult: 30, junior: 10, staff: 50 };

/** How many years a new or renewed library card is valid, by member type. */
export const CARD_YEARS = { adult: 3, junior: 1, staff: 3 };
// Days are calendar dates written as YYYY-MM-DD, read as UTC so that the server's time zone never
// shifts them.
const DAY_MS = 86_400_000;

function toTime(isoDate) {
  return Date.parse(`${isoDate}T00:00:00Z`);
}

/** Returns the calendar date `days` days after `isoDate`, or before it when `days` is negative. */
export function addDays(isoDate, days) {
  return new Date(toTime(isoDate) + days * DAY_MS).toISOString().slice(0, 10);
}

/** Returns how many days `later` is after `earlier`, negative when it is before. */
export function daysBetween(earlier, later) {
  return Math.round((toTime(later) - toTime(earlier)) / DAY_MS);
}

/** Returns the day of the week of a calendar date, 0 for Sunday to 6 for Saturday. */
export function weekdayOf(isoDate) {
  return new Date(toTime(isoDate)).getUTCDay();
}

/** Tells whether a branch is open on a calendar date. */
export function isOpenOn(branch, isoDate) {
  return !branch.closedWeekdays.includes(weekdayOf(isoDate));
}

/** Returns the first date on or after `isoDate` on which the branch is open. */
export function nextOpenDay(branch, isoDate) {
  let day = isoDate;
  while (!isOpenOn(branch, day)) day = addDays(day, 1);
  return day;
}
