test('a branch is closed on its holidays, and only on its own', () => {
  assert.equal(isOpenOn(branchById('central'), '2026-12-25'), false);
  assert.equal(isOpenOn(branchById('riverside'), '2026-12-24'), false);
  assert.equal(isOpenOn(branchById('central'), '2026-12-24'), true);
});

test('the next open day skips holidays, alone or in a row with closed weekdays', () => {
  assert.equal(nextOpenDay(branchById('central'), '2026-12-25'), '2026-12-26');
  assert.equal(nextOpenDay(branchById('riverside'), '2026-12-24'), '2026-12-26');
  assert.equal(nextOpenDay(branchById('hillcrest'), '2026-12-25'), '2026-12-28');
});
